// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// I own the mocks. Therefore I own the test behavior.
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockOnComplete = vi.fn();
const mockOnCancel = vi.fn();

const mockCartItems = [
  { id: '1', name: 'Widget', price: 29.99 },
  { id: '2', name: 'Gadget', price: 49.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({
    items: mockCartItems,
    total: 79.98,
    clearCart: mockClearCart
  })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - Complete Checkout Flow', () => {
    it('completes full checkout from shipping to confirmation', async () => {
      const user = userEvent.setup();
      render(<Checkout onComplete={mockOnComplete} onCancel={mockOnCancel} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Main St');
      await user.type(screen.getByLabelText(/city/i), 'Los Angeles');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'L Bob Rife');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/123 main st/i)).toBeInTheDocument();
      expect(screen.getByText(/\$79\.98/)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
        expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      });
      expect(mockOnComplete).toHaveBeenCalledWith('ORD-12345');
      expect(mockClearCart).toHaveBeenCalled();
    });
  });

  describe('Form Validation', () => {
    it('displays shipping errors for empty required fields', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Error States and Recovery', () => {
    it('displays payment error and allows retry', async () => {
      mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();
      render(<Checkout />);

      // Navigate to review (abbreviated)
      // ... complete shipping and payment forms ...

      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });

      // Retry
      mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-RETRY' });
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText('ORD-RETRY')).toBeInTheDocument();
      });
    });
  });

  describe('Loading States', () => {
    it('disables buttons and shows loading during submission', async () => {
      mockProcessPayment.mockImplementation(() => new Promise(() => {}));
      // ... navigate to review step ...

      await userEvent.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /processing/i })).toHaveAttribute('aria-busy', 'true');
    });
  });

  describe('Edge Cases', () => {
    it('shows empty cart message when no items', () => {
      vi.mocked(useCart).mockReturnValueOnce({ items: [], total: 0, clearCart: mockClearCart });
      render(<Checkout onCancel={mockOnCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      const results = await axe(container);
      expect(results).toHaveNoViolations();
    });

    it('provides proper navigation landmarks', () => {
      render(<Checkout />);
      expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
      expect(screen.getByRole('form', { name: /shipping information/i })).toBeInTheDocument();
    });
  });
});
